{
  "findings": [
    {
      "check_id": "CKV_GCP_26",
      "title": "VPC flow logging is not enabled",
      "resource": "google_compute_subnetwork.data_subnet",
      "severity": "MEDIUM",
      "explanation": "The subnetwork lacks a log_config block, preventing collection of VPC flow logs needed to detect and investigate suspicious network activity."
    }
  ],
  "patched_code": "resource "google_compute_subnetwork" "data_subnet" {
  name                     = "hipaa-compliant-patient-portal-subnet-data"
  ip_cidr_range            = "10.0.3.0/24"
  region                   = var.region
  network                  = google_compute_network.hipaa_vpc.id
  private_ip_google_access = true

  log_config {
    aggregation_interval = "INTERVAL_5_SEC"
    flow_sampling        = 0.5
    metadata             = "INCLUDE_ALL_METADATA"
  }
}
",
  "fix_summary": "Enabled VPC flow logging on the subnetwork to provide network traffic visibility for security monitoring and investigations."
}
